mapper.select:
select vs.scId as scid, vs.scStudentId as sid, vs.sNo as sno, vs.sName as sname, vs.scTermId as sctermid, vs.scClassId as scclassid, vs.yYear as yyear, vs.yTerm as yterm, vs.yAll as yall, vs.scCourseId as sccourseid, vs.crCode as crcode, vs.crName as crname, vs.scScore as scscore, sc.sc_regular as scRegular, sc.sc_test as scTest, sc.sc_exam as scExam, coalesce(tk.w_regular, 0.30) as wregular, coalesce(tk.w_test, 0.20) as wtest, coalesce(tk.w_exam, 0.50) as wexam, vs.scStatus as scstatus, coalesce(vs.tName, tt.tName) as tname from vwscores vs left join scoreinfo sc on sc.scId = vs.scId left join teaching tk on tk.tcTermId = vs.scTermId and tk.tcClassId = vs.scClassId and tk.tcCourseId = vs.scCourseId and tk.tcId = ( select max(tk2.tcId) from teaching tk2 where tk2.tcTermId = vs.scTermId and tk2.tcClassId = vs.scClassId and tk2.tcCourseId = vs.scCourseId ) left join teacherinfo tt on tt.tId = tk.tcTeacherId where 1 = 1
and vs.scStudentId = #{dto.sid}
and vs.scTermId = #{dto.termid}
and ( vs.crName like concat('%', #{dto.qkey}, '%') or vs.crCode like concat('%', #{dto.qkey}, '%') )
order by vs.scTermId desc, vs.scId desc
